func (h *Handler) transferOwnership(w http.ResponseWriter, r *http.Request, p authz.Principal) error {
	id, err := pathID(r, "org_id")
	if err != nil {
		return err
	}
	var body userIDBody
	if err := decode(w, r, &body); err != nil {
		return err
	}
