	}
	var out store.Record
	err = s.store.InTx(ctx, func(q *store.Q) error {
		z, old, err := s.lockRecord(ctx, q, bs, r0, authz.ActionWrite)
		if err != nil {
			return err
		}
		if z.Name != z0.Name {
			if pr, err = parseRecordInput(in, z.Name); err != nil {
