	if ferr != nil {
		return nil, nil, ferr
	}
	return &HINFOData{CPU: &cpu, OS: &os}, &dns.HINFO{Cpu: escapeForPack(cpu), Os: escapeForPack(os)}, nil
}

func (d *HINFOData) fromRR(rr dns.RR) error {
