218	func decodeError(err error) *Error {
219		var syntaxErr *json.SyntaxError
220		var typeErr *json.UnmarshalTypeError
221		var mbe *http.MaxBytesError
222		switch {
223		case errors.As(err, &mbe):
224			return BadRequest("request body is too large").WithCause(err)
225		case errors.As(err, &syntaxErr):
226			return BadRequest(fmt.Sprintf("malformed JSON at offset %d", syntaxErr.Offset)).WithCause(err)
227		case errors.Is(err, io.EOF):
228			return BadRequest("request body is required").WithCause(err)
229		case errors.Is(err, io.ErrUnexpectedEOF):
230			return BadRequest("malformed JSON").WithCause(err)
231		case errors.As(err, &typeErr):
232			if typeErr.Field != "" {
233				return BadRequest(fmt.Sprintf("field %s has wrong type", typeErr.Field)).WithCause(err)
234			}
235			return BadRequest("request body has wrong type").WithCause(err)
236		case strings.HasPrefix(err.Error(), "json: unknown field "):
237			name := strings.Trim(strings.TrimPrefix(err.Error(), "json: unknown field "), "\"")
238			return BadRequest(fmt.Sprintf("unknown field %s", name)).WithCause(err)
239		}
240		return BadRequest("malformed JSON").WithCause(err)
241	}
